# Generated by deployify. Do not edit manually; 'deployify generate' rewrites it.
#
# Drives systemd for Deployify's host target on Linux. Deployify sends this script to bash on
# standard input (locally, or through 'ssh host bash -s'), preceded by the request: the action
# in DEPLOYIFY_ACTION and every argument in an arg_* variable. Secrets travel that way, never on
# a command line. Results are printed as lines of '##deployify <key> <base64 value>'.
#
# Layout on the host, under the root (host.root, /opt/deployify by default):
#   {name}/deployify.marker                ownership marker: service, environment, release, ...
#   {name}/deployify-{name}.service        the systemd unit, linked into /etc/systemd/system
#   {name}/current -> releases/{release}   the release the unit runs
#   {name}/releases/{release}/app/         the published app
#   {name}/releases/{release}/env          its environment, secrets included (mode 600)
#   {name}/releases/{release}/run          symlink to the app's executable
#
# Needs bash, coreutils, tar and systemd; curl for http health checks. Unless it runs as root,
# the deploy user needs passwordless sudo for systemctl (and for journalctl when it is not in
# the systemd-journal group).

set -euo pipefail

out() { printf '##deployify %s %s\n' "$1" "$(printf '%s' "$2" | base64 | tr -d '\n')"; }
fail() { printf '%s\n' "$*" >&2; exit 1; }

ROOT="${arg_root:-/opt/deployify}"
ME="$(id -un)"
IS_ROOT=no; [ "$(id -u)" -eq 0 ] && IS_ROOT=yes
as_root() { if [ "$IS_ROOT" = yes ]; then "$@"; else sudo -n "$@"; fi; }
HOSTNAME_="$(hostname 2>/dev/null || uname -n)"
# Where systemctl link puts unit symlinks; overridable for Deployify's own tests only.
UNIT_DIR="${DEPLOYIFY_UNIT_DIR:-/etc/systemd/system}"

marker_field() { [ -f "$1" ] && sed -n "s/^$2=//p" "$1" | head -n 1 || true; }

service_dir() { printf '%s/%s' "$ROOT" "$arg_name"; }

# The marker says the folder is Deployify's; anything else in the way is refused.
require_owned() {
    local d; d="$(service_dir)"
    [ "$(marker_field "$d/deployify.marker" managedBy)" = deployify ] ||
        fail "'$arg_name' was not deployed by Deployify on $HOSTNAME_ ($d has no Deployify marker)."
}

restarts() { systemctl show -p NRestarts --value "$1.service" 2>/dev/null || echo 0; }

# Points current at the release (one rename, so the unit never sees a half-switched service),
# records it in the marker, and (re)starts the unit.
switch_to() {
    local d="$1" release="$2" fingerprint="$3" previous
    # The release that ran until now stays on the host, so a rollback can go back to it.
    previous="$(marker_field "$d/deployify.marker" release)"
    [ "$previous" = "$release" ] && previous="$(marker_field "$d/deployify.marker" previous)"
    ln -sfn "releases/$release" "$d/current.tmp"
    mv -Tf "$d/current.tmp" "$d/current"
    {
        printf 'managedBy=deployify\n'
        printf 'service=%s\n' "$arg_service"
        printf 'environment=%s\n' "$arg_environment"
        printf 'name=%s\n' "$arg_name"
        printf 'unit=%s\n' "$arg_unit"
        printf 'fingerprint=%s\n' "$fingerprint"
        printf 'release=%s\n' "$release"
        printf 'previous=%s\n' "$previous"
        printf 'deployedAt=%s\n' "$(date -u +%Y-%m-%dT%H:%M:%SZ)"
    } > "$d/deployify.marker.tmp"
    mv -f "$d/deployify.marker.tmp" "$d/deployify.marker"
    as_root systemctl enable "$arg_unit.service" >/dev/null 2>&1 || as_root systemctl enable "$arg_unit.service"
    as_root systemctl reset-failed "$arg_unit.service" >/dev/null 2>&1 || true
    as_root systemctl restart "$arg_unit.service"
    restarts "$arg_unit" > "$d/restarts"
}

# Keeps the newest releases. The current one and the one that ran before it always stay, so a
# rollback can go back even after an earlier rollback left an older release running.
prune() {
    local d="$1" keep="$2" current previous n=0 name
    current="$(readlink "$d/current" 2>/dev/null || true)"
    current="${current#releases/}"
    previous="$(marker_field "$d/deployify.marker" previous)"
    [ -n "$previous" ] && [ "$previous" != "$current" ] && keep=$((keep - 1))
    while IFS= read -r name; do
        [ -n "$name" ] || continue
        [ "$name" = "$current" ] && continue
        [ "$name" = "$previous" ] && continue
        n=$((n + 1))
        if [ "$n" -ge "$keep" ]; then rm -rf -- "${d:?}/releases/$name"; fi
    done < <(find "$d/releases" -mindepth 1 -maxdepth 1 -type d -printf '%T@ %f\n' 2>/dev/null | sort -rn | cut -d' ' -f2-)
    find "$d/incoming" -mindepth 1 -maxdepth 1 -mmin +60 -delete 2>/dev/null || true
}

case "$DEPLOYIFY_ACTION" in
ping)
    out host "$HOSTNAME_"
    out os "$(uname -s)"
    out user "$ME"
    command -v systemctl >/dev/null 2>&1 && out systemd yes || out systemd no
    if [ "$IS_ROOT" = yes ] || sudo -n systemctl --version >/dev/null 2>&1; then out sudo yes; else out sudo no; fi
    if [ -d "$ROOT" ]; then
        [ -w "$ROOT" ] && out root yes || out root no
    else
        parent="$(dirname "$ROOT")"
        while [ ! -d "$parent" ]; do parent="$(dirname "$parent")"; done
        [ -w "$parent" ] && out root yes || out root no
    fi
    command -v tar >/dev/null 2>&1 && out tar yes || out tar no
    command -v curl >/dev/null 2>&1 && out curl yes || out curl no
    if command -v dotnet >/dev/null 2>&1 || [ -x "${arg_dotnetroot:-/nonexistent}/dotnet" ] ||
        [ -x /usr/share/dotnet/dotnet ] || [ -x /usr/lib/dotnet/dotnet ]; then out dotnet yes; else out dotnet no; fi
    ;;

list)
    if [ -d "$ROOT" ]; then
        for m in "$ROOT"/*/deployify.marker; do
            [ -f "$m" ] || continue
            [ "$(marker_field "$m" managedBy)" = deployify ] || continue
            unit="$(marker_field "$m" unit)"
            installed=no
            [ "$(systemctl show -p LoadState --value "$unit.service" 2>/dev/null || true)" = loaded ] && installed=yes
            out service "$(cat "$m"; printf 'installed=%s\n' "$installed")"
        done
    fi
    ;;

prepare)
    if [ "$IS_ROOT" = no ] && ! sudo -n systemctl --version >/dev/null 2>&1; then
        fail "$ME can't run 'sudo -n systemctl' on $HOSTNAME_: add a sudoers rule for systemctl and journalctl, or connect as root."
    fi
    command -v systemctl >/dev/null 2>&1 || fail "systemd (systemctl) was not found on $HOSTNAME_."
    d="$(service_dir)"
    mkdir -p "$d" 2>/dev/null || fail "Can't create $d on $HOSTNAME_ as $ME: create $ROOT and give $ME ownership of it."
    if [ ! -f "$d/deployify.marker" ] && [ -n "$(find "$d" -mindepth 1 -maxdepth 1 ! -name releases ! -name incoming -print -quit 2>/dev/null)" ]; then
        fail "$d on $HOSTNAME_ already exists and was not deployed by Deployify; remove it or set host.namePrefix."
    fi
    link="$UNIT_DIR/$arg_unit.service"
    if [ ! -f "$d/deployify.marker" ] && [ -e "$link" ] && [ "$(readlink "$link" 2>/dev/null || true)" != "$d/$arg_unit.service" ]; then
        fail "systemd unit $arg_unit.service already exists on $HOSTNAME_ and was not installed by Deployify."
    fi
    mkdir -p "$d/releases" "$d/incoming"
    r="$d/releases/$arg_release"
    if [ -f "$r/.complete" ]; then
        out upload no
    else
        rm -rf -- "$r"
        out upload yes
    fi
    out incoming "$d/incoming/$arg_release.tar.gz"
    ;;

apply)
    d="$(service_dir)"
    r="$d/releases/$arg_release"
    if [ ! -f "$r/.complete" ]; then
        [ -f "$arg_archive" ] || fail "The package for $arg_release is not on $HOSTNAME_ ($arg_archive); the upload failed."
        rm -rf -- "$r"
        mkdir -p "$r/app"
        tar -xzf "$arg_archive" -C "$r/app" --no-same-owner
        case "$arg_archive" in "$d/incoming/"*) rm -f -- "$arg_archive" ;; esac
        [ -f "$r/app/$arg_entry" ] || fail "$arg_entry is not in the package for $arg_service; publish for $arg_runtime."
        chmod 755 "$r/app/$arg_entry"
        [ -f "$r/app/createdump" ] && chmod 755 "$r/app/createdump"
        ln -sfn "app/$arg_entry" "$r/run"
        (umask 077 && printf '%s' "$arg_env" > "$r/env")
        printf 'fingerprint=%s\n' "$arg_fingerprint" > "$r/release.marker"
        touch "$r/.complete"
    fi

    unit_path="$d/$arg_unit.service"
    unit_changed=no
    printf '%s' "${arg_unitfile//%DEPLOY_USER%/$ME}" > "$unit_path.tmp"
    if cmp -s "$unit_path.tmp" "$unit_path"; then rm -f "$unit_path.tmp"; else mv -f "$unit_path.tmp" "$unit_path"; unit_changed=yes; fi
    link="$UNIT_DIR/$arg_unit.service"
    if [ "$(readlink "$link" 2>/dev/null || true)" != "$unit_path" ]; then
        as_root systemctl link "$unit_path" >/dev/null
        unit_changed=yes
    fi
    [ "$unit_changed" = yes ] && as_root systemctl daemon-reload

    current="$(readlink "$d/current" 2>/dev/null || true)"
    active="$(systemctl is-active "$arg_unit.service" 2>/dev/null || true)"
    if [ "$current" = "releases/$arg_release" ] && [ "$unit_changed" = no ] && [ "$active" = active ] &&
        [ "$(marker_field "$d/deployify.marker" fingerprint)" = "$arg_fingerprint" ]; then
        out changed no
    else
        switch_to "$d" "$arg_release" "$arg_fingerprint"
        out changed yes
    fi
    prune "$d" "$arg_keep"
    ;;

activate)
    require_owned
    d="$(service_dir)"
    r="$d/releases/$arg_release"
    [ -f "$r/.complete" ] ||
        fail "Release $arg_release of '$arg_name' is no longer on $HOSTNAME_ (only the newest host.keepReleases are kept)."
    arg_service="$(marker_field "$d/deployify.marker" service)"
    arg_environment="$(marker_field "$d/deployify.marker" environment)"
    fingerprint="$(marker_field "$r/release.marker" fingerprint)"
    current="$(readlink "$d/current" 2>/dev/null || true)"
    if [ "$current" = "releases/$arg_release" ] && [ "$(systemctl is-active "$arg_unit.service" 2>/dev/null || true)" = active ]; then
        out changed no
    else
        switch_to "$d" "$arg_release" "$fingerprint"
        out changed yes
    fi
    ;;

health)
    d="$(service_dir)"
    health() { out state "$1"; out detail "$2"; exit 0; }
    [ -f "$d/deployify.marker" ] || health failed "'$arg_name' is not deployed on $HOSTNAME_"
    current="$(readlink "$d/current" 2>/dev/null || true)"
    [ "$current" = "releases/$arg_release" ] || health failed "$HOSTNAME_ runs ${current#releases/}, not $arg_release"

    declare -A p=()
    while IFS='=' read -r key value; do p[$key]="$value"; done < <(systemctl show "$arg_unit.service" \
        -p LoadState -p ActiveState -p SubState -p NRestarts -p ActiveEnterTimestampMonotonic -p ExecMainStatus 2>/dev/null || true)
    [ "${p[LoadState]:-}" = loaded ] || health failed "systemd unit $arg_unit.service is not installed on $HOSTNAME_"
    if [ "${p[ActiveState]:-}" = failed ]; then
        health failed "$arg_unit.service failed on $HOSTNAME_ (exit status ${p[ExecMainStatus]:-?}); see 'deployify logs $arg_service'"
    fi
    baseline="$(cat "$d/restarts" 2>/dev/null || echo 0)"
    if [ "${p[SubState]:-}" = auto-restart ] || [ "${p[NRestarts]:-0}" -gt "${baseline:-0}" ]; then
        health failed "$arg_unit.service keeps exiting on $HOSTNAME_ (exit status ${p[ExecMainStatus]:-?}); see 'deployify logs $arg_service'"
    fi
    [ "${p[ActiveState]:-}" = active ] || health progressing "$HOSTNAME_: ${p[ActiveState]:-unknown} (${p[SubState]:-})"

    if [ -n "${arg_port:-}" ] && command -v curl >/dev/null 2>&1; then
        url="http://$arg_healthhost:$arg_port$arg_path"
        code="$(curl -s -o /dev/null -m 10 -w '%{http_code}' "$url" 2>/dev/null || true)"
        case "$code" in
            ''|000) health progressing "no response from $url on $HOSTNAME_ yet" ;;
        esac
        [ "$code" -lt 500 ] && health healthy "HTTP $code from $url on $HOSTNAME_"
        health progressing "HTTP $code from $url on $HOSTNAME_"
    fi

    now="$(awk '{ printf "%d", $1 * 1000000 }' /proc/uptime)"
    up=$(( (now - ${p[ActiveEnterTimestampMonotonic]:-0}) / 1000000 ))
    note=""
    [ -n "${arg_port:-}" ] && note=" (curl is not installed, so only the process was checked)"
    [ "$up" -ge "${arg_startup:-10}" ] && health healthy "running for ${up}s on $HOSTNAME_$note"
    health progressing "running for ${up}s on $HOSTNAME_, waiting for ${arg_startup:-10}s"
    ;;

logs)
    journal=(journalctl)
    if [ "$IS_ROOT" = no ] && ! id -nG | tr ' ' '\n' | grep -q -x -e systemd-journal -e adm -e wheel; then
        journal=(sudo -n journalctl)
    fi
    opts=(-u "$arg_unit.service" -o json --no-pager)
    [ -n "${arg_tail:-}" ] && opts+=(-n "$arg_tail")
    [ -n "${arg_since:-}" ] && opts+=(--since "@$arg_since")
    [ "${arg_follow:-}" = yes ] && opts+=(-f)
    exec "${journal[@]}" "${opts[@]}"
    ;;

delete)
    d="$(service_dir)"
    if [ ! -d "$d" ]; then exit 0; fi
    require_owned
    as_root systemctl disable --now "$arg_unit.service" >/dev/null 2>&1 || true
    out removed "systemd unit $arg_unit.service"
    as_root systemctl daemon-reload || true
    as_root systemctl reset-failed "$arg_unit.service" >/dev/null 2>&1 || true
    rm -rf -- "${d:?}"
    out removed "folder $d"
    ;;

*)
    fail "Unknown action $DEPLOYIFY_ACTION"
    ;;
esac
